import { chromium } from 'playwright'; const BASE='https://www.statesideqm.com',THEME='158900125851',route='/collections/state-guard-series-ohio'; const b=await chromium.launch({headless:true}); const c=await b.newContext({viewport:{width:1440,height:1000}}); const p=await c.newPage(); const u=new URL(route,BASE);u.searchParams.set('preview_theme_id',THEME);await p.goto(u.href,{waitUntil:'domcontentloaded',timeout:70000});await p.waitForLoadState('load',{timeout:16000}).catch(()=>{});await p.waitForTimeout(13500);const cards=await p.evaluate(()=>[...document.querySelectorAll('[data-sqsg-view] a.sqsg-card')].map(a=>({label:(a.querySelector('strong')?.textContent||'').trim(),meta:(a.querySelector('small')?.textContent||'').trim(),href:a.getAttribute('href')||'',img:a.querySelector('img')?.currentSrc||a.querySelector('img')?.src||'',alt:a.querySelector('img')?.alt||''})));console.log('SGROOTIMAGES',JSON.stringify(cards));await c.close();await b.close();